// Generated by build.mjs from src/. Edit those files, then run `npm run build`.
(() => {
'use strict';
if (window.__immichPaperSphereButton) return;
window.__immichPaperSphereButton = true;

// Pure helpers shared by the userscript and the extension.
// build.mjs strips the `export ` keywords and inlines this file ahead of button.js.

const DEFAULT_GENERATOR_URL = 'https://sphere.schrauger.com/web/';

const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
const PHOTO_RE = new RegExp(`/photos/(${UUID})(?:/|$)`, 'i');
const SHARE_RE = /^\/(share|s)\/([^/]+)/;

/**
 * Which asset (if any) and which share (if any) an Immich page is showing.
 * Returns null on pages where the button can never apply.
 */
function parseLocation(pathname) {
  const photo = pathname.match(PHOTO_RE);
  const shareMatch = pathname.match(SHARE_RE);
  const share = shareMatch ? { [shareMatch[1] === 'share' ? 'key' : 'slug']: shareMatch[2] } : null;
  if (!photo && !share) return null;
  return { assetId: photo ? photo[1] : null, share };
}

/** The query string that authorises API calls on a share page ('' when logged in). */
function apiQuery(share) {
  if (share?.key) return `?key=${encodeURIComponent(share.key)}`;
  if (share?.slug) return `?slug=${encodeURIComponent(share.slug)}`;
  return '';
}

/** A panorama is an equirectangular image; with no projection known, an exactly 2:1 image counts. */
function isPanorama(asset) {
  if (asset?.type !== 'IMAGE') return false;
  const projection = asset.exifInfo?.projectionType;
  if (projection) return projection.toUpperCase() === 'EQUIRECTANGULAR';
  const w = asset.width ?? asset.exifInfo?.exifImageWidth;
  const h = asset.height ?? asset.exifInfo?.exifImageHeight;
  return w > 0 && h > 0 && w === 2 * h;
}

const BROWSER_READY = ['image/jpeg', 'image/png', 'image/webp'];

/**
 * The files to try, best first. A browser-ready original is preferred; anything else
 * (HEIC, RAW, …) goes as Immich's full-size JPEG rendition. Later entries are fallbacks
 * for shares that don't allow downloading the original.
 */
function downloadCandidates(asset, share) {
  const base = `/api/assets/${asset.id}`;
  const q = apiQuery(share);
  const thumb = (size) => `${base}/thumbnail${q ? q + '&' : '?'}size=${size}`;
  const fileName = asset.originalFileName || 'panorama.jpg';
  const originalOk = BROWSER_READY.includes(asset.originalMimeType);
  const jpgName = originalOk ? fileName : fileName.replace(/\.[^.]*$/, '') + '.jpg';
  const list = [];
  if (originalOk) list.push({ path: `${base}/original${q}`, name: fileName, reduced: false });
  list.push({ path: thumb('fullsize'), name: jpgName, reduced: originalOk });
  list.push({ path: thumb('preview'), name: jpgName, reduced: true });
  return list;
}

function httpUrl(input) {
  try {
    const url = new URL(String(input).trim());
    return url.protocol === 'http:' || url.protocol === 'https:' ? url : null;
  } catch {
    return null;
  }
}

/** A typed generator URL, the default when left blank, or null when it isn't an http(s) URL. */
function normalizeGeneratorUrl(input) {
  if (!String(input ?? '').trim()) return DEFAULT_GENERATOR_URL;
  return httpUrl(input)?.href ?? null;
}

/** The origin of a typed Immich host address, or null when it isn't an http(s) URL. */
function immichOrigin(input) {
  return httpUrl(input)?.origin ?? null;
}

/** The generator address that asks it to wait for a handoff. */
function handoffUrl(generatorUrl) {
  return generatorUrl.replace(/#.*$/, '') + '#from-opener';
}

/** Only the tab this click opened, at the configured generator origin, may ask for the photo. */
function isReadyMessage(event, win, generatorOrigin) {
  return event.source === win && event.origin === generatorOrigin && event.data?.type === 'paper-sphere-ready';
}

/**
 * Download the panorama and send it to the generator tab once it is ready.
 * - every download fails → close the tab and throw that error
 * - `timeout` settles before `ready` → throw, leaving the tab open
 * Resolves with whether a reduced-size copy was sent.
 */
async function runHandoff({ win, candidates, fetchBlob, ready, timeout, post }) {
  const download = (async () => {
    let lastError;
    for (const c of candidates) {
      try {
        return { blob: await fetchBlob(c.path), candidate: c };
      } catch (e) {
        lastError = e;
      }
    }
    win.close();
    throw lastError;
  })();
  const readyOrTimeout = Promise.race([
    ready,
    timeout.then(() => { throw new Error("Generator didn't respond — check the generator URL"); }),
  ]);
  const [{ blob, candidate }] = await Promise.all([download, readyOrTimeout]);
  post({ type: 'paper-sphere-image', name: candidate.name, blob });
  return { reduced: candidate.reduced };
}

// Extension settings for the content script: the generator URL from the options page.
function getGeneratorUrl() {
  const api = globalThis.browser ?? chrome;
  return api.storage.sync.get('generatorUrl').then((s) => s.generatorUrl);
}

// The floating "Make paper sphere" button. Plain script: build.mjs inlines core.js above it,
// and each build target defines getGeneratorUrl() → Promise<string> before this runs.

const READY_TIMEOUT_MS = 20000;
const MESSAGE_MS = 4000;
const LABEL = 'Make paper sphere';

let generatorUrl = DEFAULT_GENERATOR_URL;
const refreshGeneratorUrl = () =>
  getGeneratorUrl().then((u) => { generatorUrl = u || DEFAULT_GENERATOR_URL; }, () => {});
refreshGeneratorUrl();

const button = document.createElement('button');
button.type = 'button';
button.textContent = LABEL;
button.style.cssText = [
  'position:fixed', 'left:16px', 'bottom:100px', // clears the viewer's 83 px thumbnail strip
  'z-index:2147483647', 'display:none',
  'padding:10px 16px', 'border:0', 'border-radius:999px', 'cursor:pointer',
  'font:600 14px/1.2 system-ui,sans-serif', 'color:#fff', 'background:#4250af',
  'box-shadow:0 2px 8px rgba(0,0,0,.4)', 'max-width:calc(100vw - 32px)',
].join(';');

let current = null; // { asset, share } for the panorama on screen, or null
let busy = false;
let lastPath = null;
let lookup = 0; // ignores answers to lookups made for a page we've since left

function show(visible) {
  button.style.display = visible ? 'block' : 'none';
}

function flash(text) {
  button.textContent = text;
  setTimeout(() => { if (!busy) button.textContent = LABEL; }, MESSAGE_MS);
}

async function getJson(path) {
  const res = await fetch(location.origin + path, { credentials: 'same-origin' });
  if (!res.ok) throw new Error(`Immich returned ${res.status}`);
  return res.json();
}

async function onLocationChange() {
  if (location.pathname === lastPath) return;
  lastPath = location.pathname;
  const id = ++lookup;
  current = null;
  if (!busy) show(false);
  const where = parseLocation(location.pathname);
  if (!where) return;
  try {
    const q = apiQuery(where.share);
    let asset;
    if (where.assetId) {
      asset = await getJson(`/api/assets/${where.assetId}${q}`);
    } else {
      const link = await getJson(`/api/shared-links/me${q}`);
      if (link.assets?.length !== 1) return;
      asset = link.assets[0];
      // The share listing may leave out details; ask for the asset itself.
      asset = await getJson(`/api/assets/${asset.id}${q}`).catch(() => asset);
    }
    if (id !== lookup || !isPanorama(asset)) return;
    current = { asset, share: where.share };
    show(true);
  } catch {
    // Not viewable with this session (or not an asset): leave the button hidden.
  }
}

async function fetchBlob(path) {
  const res = await fetch(location.origin + path, { credentials: 'same-origin' });
  if (!res.ok) throw new Error(`Download failed (${res.status})`);
  return res.blob();
}

function onClick() {
  if (busy || !current) return;
  const target = generatorUrl;
  // Must open synchronously within the click, or it's treated as a blocked popup.
  const win = window.open(handoffUrl(target), '_blank');
  refreshGeneratorUrl();
  if (!win) {
    flash('Pop-up blocked — allow pop-ups for this site');
    return;
  }
  const origin = new URL(target).origin;
  let onMessage;
  const ready = new Promise((resolve) => {
    onMessage = (e) => { if (isReadyMessage(e, win, origin)) resolve(); };
    window.addEventListener('message', onMessage);
  });
  let timer;
  const timeout = new Promise((resolve) => { timer = setTimeout(resolve, READY_TIMEOUT_MS); });

  busy = true;
  button.disabled = true;
  button.textContent = 'Sending…';
  const { asset, share } = current;
  runHandoff({
    win,
    candidates: downloadCandidates(asset, share),
    fetchBlob,
    ready,
    timeout,
    post: (message) => win.postMessage(message, origin),
  }).then(
    ({ reduced }) => {
      busy = false;
      if (reduced) flash("Sent a reduced-size copy (share doesn't allow downloads)");
      else button.textContent = LABEL;
    },
    (err) => {
      busy = false;
      flash(err?.message || String(err));
    },
  ).finally(() => {
    window.removeEventListener('message', onMessage);
    clearTimeout(timer);
    button.disabled = false;
    if (!current) show(false);
  });
}

button.addEventListener('click', onClick);
(document.body || document.documentElement).appendChild(button);

// Immich is a single-page app: follow its navigation.
for (const method of ['pushState', 'replaceState']) {
  const original = history[method];
  history[method] = function (...args) {
    const result = original.apply(this, args);
    onLocationChange();
    return result;
  };
}
window.addEventListener('popstate', onLocationChange);
setInterval(onLocationChange, 1000);
onLocationChange();
})();
